let env = msg.payload;
if (!env || env.type !== "text" || env.payload === undefined) return null;

let raw = env.payload;
// Meshtastic publishes the payload already decoded as an object when the radio message text is valid JSON (our case); for simple text it arrives as a string inside payload.text.
if (raw !== null && typeof raw === "object") {
    raw = (typeof raw.text === "string") ? raw.text : JSON.stringify(raw);
}

if (typeof raw !== "string") return null;

msg.payload = raw;
return msg;

let p = msg.payload;
let now = new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' });

let icon = "🚨";
if (p.src === "PRUA") icon = "⚓ 🚨";
if (p.src === "CABINA") icon = "🚪 🚨";
if (p.src === "PIR") icon = "🚶 🚨";

let text = `${icon} *MESHBOATGUARD INTRUSION ALARM* ${icon}\n\n`;
text += `📌 *Device:* \`${p.dev}\`\n`;
text += `📍 *Triggered Zone:* \`${p.src}\`\n`;
text += `🛡️ *System State:* \`${p.s === "ARM" ? "ARMED" : "DISARMED"}\`\n`;
text += `🌡️ *Temperature:* ${p.tmp} °C | 💧 *Humidity:* ${p.hum}%\n`;
text += `🔋 *Boat Battery:* ${p.bat}%\n`;
text += `⏱️ *Event Time:* ${now}`;

msg.payload = {
    chatId: msg.chatId || env.get("TELEGRAM_DEFAULT_CHAT_ID"),
    type: "message",
    content: text,
    options: { parse_mode: "Markdown" }
};
return msg;

let p = msg.payload;
let now = new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' });

let text = `📊 *MESHBOATGUARD TELEMETRY*\n\n`;
text += `📌 *Device:* \`${p.dev}\`\n`;
text += `🛡️ *System State:* \`${p.s === "ARM" ? "ARMED" : "DISARMED"}\`\n`;
text += `🌡️ *Temperature:* ${p.tmp} °C | 💧 *Humidity:* ${p.hum}%\n`;
text += `🔋 *Boat Battery:* ${p.bat}%\n`;
text += `⏱️ *Updated:* ${now}`;

msg.payload = {
    chatId: msg.chatId || env.get("TELEGRAM_DEFAULT_CHAT_ID"),
    type: "message",
    content: text,
    options: { parse_mode: "Markdown" }
};
return msg;

let p = msg.payload;
let statusStr = p.s === "ARM" ? "🔒 ARMED" : "🔓 DISARMED";
let text = `✅ *MESHBOATGUARD COMMAND CONFIRMATION*\n\nSystem state updated: *${statusStr}*`;

msg.payload = {
    chatId: msg.chatId || env.get("TELEGRAM_DEFAULT_CHAT_ID"),
    type: "message",
    content: text,
    options: { parse_mode: "Markdown" }
};
return msg;

let text = msg.payload.content || "";
let chatId = msg.payload.chatId;

let responseMsg = "";
let cmdPayload = "";

if (text.startsWith("/arm")) {
    cmdPayload = '{"cmd":"ARM","val":1}';
    responseMsg = "🔒 *Arm command sent to the boat via Meshtastic...*";
} else if (text.startsWith("/disarm")) {
    cmdPayload = '{"cmd":"ARM","val":0}';
    responseMsg = "🔓 *Disarm command sent to the boat via Meshtastic...*";
} else if (text.startsWith("/status")) {
    cmdPayload = '{"cmd":"STAT"}';
    responseMsg = "ℹ️ *Status and telemetry request sent via Meshtastic...*";
} else {
    responseMsg = "⚓ *MeshBoatGuard Bot Commands:*\n\n/arm - Arm the onboard security system\n/disarm - Disarm the onboard security system\n/status - Request updated state, weather and battery data";
}

let outputs = [null, null];

if (responseMsg) {
    outputs[0] = {
        payload: {
            chatId: chatId,
            type: "message",
            content: responseMsg,
            options: { parse_mode: "Markdown" }
        }
    };
}

if (cmdPayload) {
    outputs[1] = { payload: cmdPayload };
}

return outputs;

let downlinkTopic = env.get("MESHTASTIC_MQTT_DOWNLINK_TOPIC");
if (!downlinkTopic) {
    node.warn("MESHTASTIC_MQTT_DOWNLINK_TOPIC not set in .env: command not sent");
    return null;
}
// Meshtastic firmware requires 'from' to match the gateway nodeNum receiving the downlink: we parse it from the hex ID in the topic.
let hexId = downlinkTopic.split("!").pop();
let fromNum = parseInt(hexId, 16);
msg.topic = downlinkTopic;
msg.payload = JSON.stringify({
    from: fromNum,
    type: "sendtext",
    channel: 0, // channel index for 'meshboat' (the 'mqtt' channel acts just as a gate to downlink)
    payload: msg.payload // simple string, not an object
});
return msg;

let p = msg.payload;
if (!p || !p.dev) return null;

let measurement = "meshboatguard_telemetry";
let line = `${measurement},device=${p.dev},source=${p.src||'UNK'},msg_type=${p.t||'TEL'} `;

let fields = [];
if (p.tmp !== undefined) fields.push(`temperature=${parseFloat(p.tmp)}`);
if (p.hum !== undefined) fields.push(`humidity=${parseFloat(p.hum)}`);
if (p.bat !== undefined) fields.push(`battery=${parseInt(p.bat)}`);
if (p.s !== undefined) fields.push(`armed=${p.s === 'ARM' ? 1 : 0}`);
fields.push(`alarm_active=${p.t === 'ALM' ? 1 : 0}`);

line += fields.join(",");

msg.payload = line;
msg.headers = {
    "Authorization": "Token meshboatguard_secret_token_12345",
    "Content-Type": "text/plain; charset=utf-8"
};
return msg;
